int ans=0;
void countArraysUtil(vector<int >&arr,int X,int K,int xorVal) {
    if(X==0) {
        int cnt=0;
        for(int i=0;i<arr.size();i ++) {
            if(arr[i]> xorVal)cnt++;
        }
        if(cnt>=K)ans ++;
        return ;
    }
    int temp=arr[0];
    arr.erase(arr.begin());
    countArraysUtil(arr,X-1,K,xorVal);
    arr.insert(arr.begin(),temp);
    temp=arr.back();
    arr.pop_back();
    countArraysUtil(arr,X-1,K,xorVal);
    arr.push_back(temp);
    arr[0]++;
    countArraysUtil(arr,X-1,K,xorVal);
    arr[0]--;
    arr[arr.size()-1]++;
    countArraysUtil(arr,X-1,K,xorVal);
    arr[arr.size()-1]-- ;
}
