int dfs(const vector<int>& arr, int d, int pos, vector<int>& dp){

        if(dp[pos] != -1) return dp[pos];

        int res = 1;
        for(int i = pos - 1; i >= 0 && i >= pos - d; i --)
            if(arr[i] < arr[pos])
                res = max(res, 1 + dfs(arr, d, i, dp));
            else break;

        for(int i = pos + 1; i < arr.size() && i <= pos + d; i ++)
            if(arr[i] < arr[pos])
                res = max(res, 1 + dfs(arr, d, i, dp));
            else break;

        return dp[pos] = res;
    }

