    vector<int>maxValue(R+1);
    for(int i=1;i<R+1;i ++) {
        parent[i]= maxValue[i]= i ;
    }
    for(int i=0;i<N;i ++) {
        Union(parent,rank,maxValue,arr[i ].first,arr[i ].second);
    }
    for(int i=0;i<M;i ++) {
        int P=Find(parent,queries[i]);
        cout<<maxValue[P]<< " ? " ;
    }
}

int solve(int y, int x, int s) {
    if(s == 2) return 2 * y + x;
    s >>= 1;
    int ny = y / s, nx = x / s;
    int nxt = ny * 2 + nx;
    return s * s * nxt + solve(y - ny * s, x - nx * s, s);
}

