class StackWithMax {
    stack<int>mainStack;
    stack<int>trackStack;
    public:void push(int x) {
        mainStack.push(x);
        if(mainStack.size()==1) {
            trackStack.push(x);
            return ;
        }
        if(x>trackStack.top())trackStack.push(x);
        else trackStack.push(trackStack.top());
    }
    int getMax() {
        return trackStack.top() ;
    }
    int pop() {
        mainStack.pop();
        trackStack.pop() ;
    }
}
