int atMostNGivenDigitSet(const string& dset, const string& snum,
                             vector<int>& dp){

        if(snum.size() == 0)
            return 1;

        if(dp[snum.size()] != -1)
            return dp[snum.size()];

        int res = 0;
        for(int i = 0; i < dset.size(); i ++)
            if(dset[i] < snum[0])
                res += (int)pow(dset.size(), snum.size() - 1);
            else if(dset[i] == snum[0])
                res += atMostNGivenDigitSet(dset, snum.substr(1), dp);
            else
                break;

        return dp[snum.size()] = res;
    }

