int packRecursive(int n, int W, int *w, int *v) {
    // 结束条件（初始条件），i或者j为0时最大总价值为0
    if (n == 0 || W == 0) {
        return 0;
    }
    // 第i个物品不能装下，则递归装i-1个
    if (w[n] > W) {
        return packRecursive(n - 1, W, w, v);
    }
    //第i个物品能装下，则比较包括第i个物品和不包括第i个物品，取其最大值
    else {
        return max(v[n] + packRecursive(n - 1, W - w[n], w, v), packRecursive(n - 1, W, w, v));
    }
}

int ComputeNumberOfWaysToH(int h, int maximum_step,
                           vector<int>* number_of_ways_to_h_ptr) {
  if (h <= 1) {
    return 1;
  }

  vector<int>& number_of_ways_to_h = *number_of_ways_to_h_ptr;
  if (number_of_ways_to_h[h] == 0) {
    for (int i = 1; i <= maximum_step && h - i >= 0; ++i) {
      number_of_ways_to_h[h] +=
          ComputeNumberOfWaysToH(h - i, maximum_step, number_of_ways_to_h_ptr);
    }
  }
  return number_of_ways_to_h[h];
}

int dfs(const string& s, int start, set<string>& bag){

        if(start == s.size())
            return bag.size();

        int res = 0;
        for(int end = start; end <= s.size(); end ++)
            if(!bag.count(s.substr(start, end - start + 1))){
                bag.insert(s.substr(start, end - start + 1));
                res = max(res, dfs(s, end + 1, bag));
                bag.erase(s.substr(start, end - start + 1));
            }
        return res;
    }

int numSquares(int n, vector<int>& mem){

        if(n == 0)
            return 0;

        if(mem[n] != -1)
            return mem[n];

        int res = INT_MAX;
        for(int i = 1; n - i * i >= 0; i ++ )
            res = min(res, 1 + numSquares(n - i * i, mem));
        return mem[n] = res;
    }

