}

bool dfs(int x, vector<int>& dp, bool isAlice){

        if(x == 1) return isAlice ? false : true;

        if(dp[x] != -1) return dp[x];

        if(isAlice){
            for(int i = 1; i * i <= x; i ++)
                if(x % i == 0 && dfs(x - i, dp, false))
                    return dp[x] = true;
            return dp[x] = false;
        }
        else{
            for(int i = 1; i * i <= x; i ++)
                if(x % i == 0 && !dfs(x - i, dp, true))
                    return dp[x] = false;
            return dp[x] = true;
        }
    }

