long long possibleNumbers(int pos,int previous,bool tight,bool start,string N,int K) {
    if(pos==N.length())return 1;
    if(dp[pos ][previous ][tight ][start]!= -1)return dp[pos ][previous ][tight ][start];
    int res=0;
    int upper_limit =(tight)?(N[pos]- '0'): 9;
    int new_tight;
    if(! start) {
        res=possibleNumbers(pos+1,previous,false,false,N,K);
        for(int i=1;i<=upper_limit;i ++) {
            new_tight =(tight&&i==upper_limit)? 1:0;
            res+=possibleNumbers(pos+1,i,new_tight,true,N,K);
        }
    }
    else {
        for(int i=0;i<=upper_limit;i ++) {
            new_tight =(tight&&i==upper_limit)? 1:0;
            if(abs(i-previous)<= K)res+=possibleNumbers(pos+1,i,new_tight,true,N,K);
        }
    }
    dp[pos ][previous ][tight ][start]= res;
    return dp[pos ][previous ][tight ][start];
}

