static int getDivisors(int min,int n) {
    int total=0;
    for(int i=min;i<n;++ i) {
        if(n%i==0&&n/i>=i) {
            ++total;
            if(n/i>i)total+=getDivisors(i,n/i);
        }
    }
    return total;
}

