vector<vector<int>>dp;
int solveUtil(int start,int bucket,string str,int K) {
    int N=str.size();
    if(start==N) {
        if(bucket==K)return 0;
        return INT_MAX ;
    }
    if(bucket==K)return INT_MAX;
    if(dp[start ][bucket]!= -1)return dp[start ][bucket];
    int zeroes=0;
    int ones=0;
    int ans=INT_MAX;
    for(int i=start;i<N;++ i) {
        if(str[i]== '1')ones ++;
        else zeroes ++;
        if(ones*zeroes>ans)break;
        int temp=solveUtil(i+1,bucket+1,str,K);
        if(temp!=INT_MAX) {
            ans=min(ans,temp +(ones*zeroes)) ;
        }
    }
    return dp[start ][bucket]= ans ;
}
int solve(string str,int K) {
    int N=str.size();
    dp.clear();
    dp.resize(N,vector<int >(K,-1));
    int ans=solveUtil(0,0,str,K);
    return ans==INT_MAX ? -1:ans;
}

