int checkRecursive(int x,int n,int curr_num=1,int curr_sum=0) {
    int results=0;
    int p=power(curr_num,n);
    while(p+curr_sum<x) {
        results+=checkRecursive(x,n,curr_num+1,p+curr_sum);
        curr_num ++;
        p=power(curr_num,n);
    }
    if(p+curr_sum==x)results ++;
    return results;
}

