int ways(int n) {
    if(n<3) {
        return 0 ;
    }
    int c2=0;
    int c1=n-3;
    int l=c1+1;
    int s=0;
    int exp_c2=c1/2;
    while(exp_c2>=c2) {
        int f1=factorial(l);
        int f2=factorial(c1);
        int f3=factorial(c2);
        int f4 =(f2*f3);
        s+=f1/f4;
        c2+=1;
        c1-=2;
        l-=1 ;
    }
    return s;
}

