}
vector<int>generatePalindromes(int N) {
    vector<int>palindromes;
    int number;
    for(int j=0;j<2;j ++) {
        int i=1;
        while(( number=createPalindrome(i ++,j))<=N)palindromes.push_back(number);
    }
    return palindromes ;
}
long long minimumSubsetSize(vector<int >&A,int i,int j,int N) {
    if(! N)return 0;
    if(i>j A[i]> N)return INT_MAX;
    if(dp[i ][N]) return dp[i ][N];
    dp[i ][N]= min(1+minimumSubsetSize(A,i+1,j,N-A[i]),minimumSubsetSize(A,i+1,j,N));
    return dp[i ][N];
}
int minimumNoOfPalindromes(int N) {
    vector<int>palindromes=generatePalindromes(N);
    sort(palindromes.begin(),palindromes.end());
    dp=vector<vector<long long >>(palindromes.size(),vector<long long >(N+1,0));
    return minimumSubsetSize(palindromes,0,palindromes.size()-1,N);
}

using namespace std;
int binarySearch(string*arr,int low,int high,string x) {
    if(low>high)return -1;
    int mid =(low+high)/ 2;
    if(arr[mid]== " ") {
        int left=mid-1;
        int right=mid+1;
        while(1) {
            if(left<low&&right>high)return -1;
            if(left>=low&&arr[left]!= " ") {
                mid=left;
                break ;
            }
            else if(right<=high&&arr[right]!= " ") {
                mid=right;
                break ;
            }
            left --;
            right++;
        }
    }
    if(arr[mid]== x)return mid;
    else if(arr[mid]> x)return binarySearch(arr,low,mid-1,x);
    else return binarySearch(arr,mid+1,high,x);
}
int sparseSearch(string arr[],string x,int n) {
    return binarySearch(arr,0,n-1,x);
}

Node* build(const string& exp, int l, int r, const vector<int>& match){

        if(l == r){
//            assert(isdigit(exp[l]));
            return new Node('v', exp[l] - '0');
        }

        if(exp[r] == ')'){
            if(match[r] == l) return build(exp, l + 1, r - 1, match);

            Node* right = build(exp, match[r], r, match);
//            assert(exp[match[r] - 1] == '|' || exp[match[r] - 1] == '&');
//            assert(l <= exp[match[r] - 2]);
            Node* left = build(exp, l, match[r] - 2, match);
            return new Node(exp[match[r] - 1],
                            exp[match[r] - 1] == '|' ? (left->val | right->val) : (left->val & right->val),
                            left, right);
        }

//        assert(isdigit(exp[r]));
//        assert(exp[r - 1] == '&' || exp[r - 1] == '|');
//        assert(l <= r - 2);
        Node* right = new Node('v', exp[r] - '0');
        Node* left = build(exp, l, r - 2, match);
        return new Node(exp[r - 1],
                        exp[r - 1] == '|' ? (left->val | right->val) : (left->val & right->val),
                        left, right);
    }

