vector<int>arr(1000000), tree(4*arr.size());
int combine(int a,int b) {
    if(a!=0&&b!=0) {
        return a ;
    }
    if(a>=b) {
        return a ;
    }
    return b ;
}
void buildTree(int ind,int low,int high,int x) {
    if(low==high) {
        if(arr[low]> x) {
            tree[ind]= arr[low];
        }
        else {
            tree[ind]= 0 ;
        }
        return ;
    }
    int mid =(low+high)/ 2;
    buildTree(2*ind+1,low,mid,x);
    buildTree(2*ind+2,mid+1,high,x);
    tree[ind]= combine(tree[2*ind+1], tree[2*ind+2]) ;
}
int query(int ind,int low,int high,int l,int r) {
    int mid =(low+high)/ 2;
    if(low>r high<l) {
        return 0 ;
    }
    if(l<=low&&r>=high) {
        return tree[ind];
    }
    return combine(query(2*ind+1,low,mid,l,r), query(2*ind+2,mid+1,high,l,r));
}

ull divsum(ull to, ull c, ull k, ull m) {
    ull res = k / m * sumsq(to) + c / m * to;
    k %= m; c %= m;
    if (!k) return res;
    ull to2 = (to * k + c) / m;
    return res + (to - 1) * to2 - divsum(to2, m-1 - c, m, k);
}

