void FrontToLast(queue<int >&q,int qsize) {
    if(qsize<=0)return;
    q.push(q.front());
    q.pop();
    FrontToLast(q,qsize-1);
}
void pushInQueue(queue<int >&q,int temp,int qsize) {
    if(q.empty() qsize==0) {
        q.push(temp);
        return ;
    }
    else if(temp<=q.front()) {
        q.push(temp);
        FrontToLast(q,qsize);
    }
    else {
        q.push(q.front());
        q.pop();
        pushInQueue(q,temp,qsize-1);
    }
}
void sortQueue(queue<int >&q) {
    if(q.empty())return;
    int temp=q.front();
    q.pop();
    sortQueue(q);
    pushInQueue(q,temp,q.size());
}

void dfs(int len, int index, long long num, long long low, long long high,
             set<int>& set){

        if(low <= num && num <= high) set.insert(num);

        if(index < len){
            int last = num % 10;
            if(last - 1 >= 0) dfs(len, index + 1, num * 10ll + (last - 1ll), low, high, set);
            if(last + 1 <= 9) dfs(len, index + 1, num * 10ll + (last + 1ll), low, high, set);
        }
    }

int countAndMergeSort(vector<long long> *sums, int start, int end, int lower, int upper) {
        if (end - start <= 0) {  // The number of range [start, end] of which size is less than 2 is always 0.
            return 0;
        }
        int mid = start + (end - start) / 2;
        int count = countAndMergeSort(sums, start, mid, lower, upper) +
                    countAndMergeSort(sums, mid + 1, end, lower, upper);
        int j = mid + 1, k = mid + 1, r = mid + 1;
        vector<long long> tmp;
        for (int i = start; i <= mid; ++i) {
            // Count the number of range sums that lie in [lower, upper].
            while (k <= end && (*sums)[k] - (*sums)[i] < lower) {
                ++k;
            }
            while (j <= end && (*sums)[j] - (*sums)[i] <= upper) {
                ++j;
            }
            count += j - k;

            // Merge the two sorted arrays into tmp.
            while (r <= end && (*sums)[r] < (*sums)[i]) {
                tmp.emplace_back((*sums)[r++]);
            }
            tmp.emplace_back((*sums)[i]);
        }
        // Copy tmp back to sums.
        copy(tmp.begin(), tmp.end(), sums->begin() + start);
        return count;
    }
